    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    candidates = [v for v in counts if v != background]
    if not candidates:
        return out
    fill = min(candidates, key=lambda v: counts[v])
    endpoints = {(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
                 if grid[r][c] != background}

    # Each multi-cell run on a border is a bar. Its cells project inward
    # perpendicular to that border, filling until the first isolated marker.
    # Corner cells are assigned to the longer boundary run so a long bar
    # touching a corner is not misread as a second one-cell bar.
    rays = []
    for row in (0, h - 1):
        c = 0
        while c < w:
            value = grid[row][c]
            if value == background:
                c += 1
                continue
            start = c
            while c < w and grid[row][c] == value:
                c += 1
            if c - start >= 2:
                dr = 1 if row == 0 else -1
                rays.extend((row, cc, dr, 0) for cc in range(start, c))
    for col in (0, w - 1):
        r = 0
        while r < h:
            value = grid[r][col]
            if value == background:
                r += 1
                continue
            start = r
            while r < h and grid[r][col] == value:
                r += 1
            if r - start >= 2:
                dc = 1 if col == 0 else -1
                rays.extend((rr, col, 0, dc) for rr in range(start, r))

    for r, c, dr, dc in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if (rr, cc) in endpoints:
                out[rr][cc] = 4
                break
            if grid[rr][cc] == background:
                out[rr][cc] = fill
            rr += dr
            cc += dc
    return out

